package com.vandorlabs.vehicle;

import com.vandorlabs.gear.*;
import com.vandorlabs.gear.core.GearMotion;
import com.vandorlabs.physics.*;
import java.lang.reflect.*;
import java.util.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.Vec3d;

/** Actual Source descriptor callbacks plus independent actual payload point checks. No runtime binding. */
public final class VehicleCouplerPoseConstraintChecks {
 private static int checks,profiles;private static Method make;private static volatile double sink;
 private static void need(boolean b,String why){checks++;if(!b)throw new AssertionError("Source pose kernel: "+why);}
 private static GearTileEntity arm(GearMotion.Mode mode,EnumFacing face,int size,int height)throws Exception{return (GearTileEntity)make.invoke(null,mode,face,size,GearMotion.Direction.NORTH,height,90D,0D);}
 private static CouplerArmConstraint.Stroke stroke(double min,double max,double requested){return new CouplerArmConstraint.Stroke(min,max,requested);}
 private static CouplerGraphConstraint.Graph graph(int links){List<CouplerGraphConstraint.Link> list=new ArrayList<>();for(int i=0;i<links;i++)list.add(new CouplerGraphConstraint.Link(0,1));return new CouplerGraphConstraint.Graph(2,0,list);}
 private static void point(CouplerPoseConstraint.Result result,int body,Vec3d local,double[] out){for(int axis=0;axis<3;axis++){double x=axis==0?result.translation(body,0):axis==1?result.translation(body,1):result.translation(body,2);x+=result.rotation(body,axis,0)*local.x+result.rotation(body,axis,1)*local.y+result.rotation(body,axis,2)*local.z;out[axis]=x;}}
 private static void single()throws Exception{CouplerGraphConstraint.Graph graph=graph(1);CouplerPoseConstraint.Workspace work=new CouplerPoseConstraint.Workspace(graph,1);double[] actual=new double[3],other=new double[3];for(EnumFacing face:EnumFacing.values())for(GearMotion.Mode mode:new GearMotion.Mode[]{GearMotion.Mode.EXTEND,GearMotion.Mode.ROTATE,GearMotion.Mode.ROTATE_LEVEL})for(int size:new int[]{1,2})for(int height:new int[]{1,3,8}){GearTileEntity owner=arm(mode,face,size,height);NBTTagCompound before=owner.payload().write();VehicleArmConstraintModel model=new VehicleArmConstraintModel(new VehicleArmConstraintModel.Arm[]{VehicleArmConstraintModel.Arm.capture(owner)},new VehicleArmConstraintModel.Endpoint[]{new VehicleArmConstraintModel.Endpoint(0,.5,-.25,3.75),new VehicleArmConstraintModel.Endpoint(-1,2,3,4)});for(int axis=0;axis<3;axis++)for(double phase:new double[]{0,.125,.4,.75,1}){double[] vector={0,0,0};vector[axis]=1;RigidTransform prior=RigidTransform.rotation(vector[0],vector[1],vector[2],37);CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(model,graph,new CouplerArmConstraint.Stroke[]{stroke(0,1,phase)},new boolean[]{true},new RigidTransform[]{RigidTransform.IDENTITY,prior},work);need(result.accepted()&&result.phase(0)==phase,"actual all-six-mount/mode/size hard phase "+result.failure);Vec3d source=owner.payload().transform(owner,phase,.5,-.25,3.75).addVector(owner.getPos().getX(),owner.getPos().getY(),owner.getPos().getZ());point(result,0,source,actual);point(result,1,new Vec3d(2,3,4),other);for(int k=0;k<3;k++)need(Math.abs(actual[k]-other[k])<=1e-7,"actual Source payload head matches independently transformed native point");for(int k=0;k<9;k++)need(result.transform(1).r[k]==prior.r[k],"single pair keeps free proper prior axes");profiles++;}need(owner.progress()==.4&&before.equals(owner.payload().write()),"live Source phase/payload unchanged");}}
 private static final class Scene {final GearTileEntity[] owners;final VehicleArmConstraintModel model;final CouplerGraphConstraint.Graph graph;final CouplerPoseConstraint.Workspace work;final Vec3d anchor;Scene(int arms)throws Exception{owners=new GearTileEntity[arms];VehicleArmConstraintModel.Arm[] frozen=new VehicleArmConstraintModel.Arm[arms];VehicleArmConstraintModel.Endpoint[] endpoints=new VehicleArmConstraintModel.Endpoint[arms*2];for(int i=0;i<arms;i++){owners[i]=arm(GearMotion.Mode.EXTEND,EnumFacing.NORTH,1,3);frozen[i]=VehicleArmConstraintModel.Arm.capture(owners[i]);}anchor=owners[0].payload().transform(owners[0],.4,0,0,0).addVector(owners[0].getPos().getX(),owners[0].getPos().getY(),owners[0].getPos().getZ());for(int i=0;i<arms;i++){endpoints[i*2]=new VehicleArmConstraintModel.Endpoint(i,0,0,i*2);endpoints[i*2+1]=new VehicleArmConstraintModel.Endpoint(-1,anchor.x,anchor.y,anchor.z+i*2);}model=new VehicleArmConstraintModel(frozen,endpoints);graph=graph(arms);work=new CouplerPoseConstraint.Workspace(graph,arms);}}
 private static CouplerPoseConstraint.Result fit(Scene scene,double command,double previous,double angle){int n=scene.owners.length;CouplerArmConstraint.Stroke[] s=new CouplerArmConstraint.Stroke[n];for(int i=0;i<n;i++)s[i]=stroke(0,1,i==0?command:previous);boolean[] driven=new boolean[n];driven[0]=true;return CouplerPoseConstraint.solve(scene.model,scene.graph,s,driven,new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.rotation(0,0,1,angle)},scene.work);}
 private static void sourceContacts(Scene scene,CouplerPoseConstraint.Result result){need(result.accepted(),"Source multi-pair fit "+result.failure+" error="+result.error+" work="+result.workOps);double[] a=new double[3],b=new double[3];for(int i=0;i<scene.owners.length;i++){GearTileEntity owner=scene.owners[i];Vec3d actual=owner.payload().transform(owner,result.phase(i),0,0,i*2).addVector(owner.getPos().getX(),owner.getPos().getY(),owner.getPos().getZ());point(result,0,actual,a);point(result,1,scene.anchor.addVector(0,0,i*2),b);for(int k=0;k<3;k++)need(Math.abs(a[k]-b[k])<=1.01e-7,"independent actual Source multi-pair contact");}profiles++;}
 private static void commands()throws Exception{Scene scene=new Scene(2);double previous=.6;for(int i=0;i<8;i++){double command=.15+i*.09,angle=-50+i*15;CouplerPoseConstraint.Result result=fit(scene,command,previous,angle);sourceContacts(scene,result);need(result.phase(0)==command,"Source driven command remains hard while Z prior changes");RigidTransform r=RigidTransform.rotation(0,0,1,angle);for(int k=0;k<9;k++)need(Math.abs(result.transform(1).r[k]-r.r[k])<2e-5,"Source axial rotation remains free");previous=result.phase(1);}CouplerPoseConstraint.Result compatible=CouplerPoseConstraint.solve(scene.model,scene.graph,new CouplerArmConstraint.Stroke[]{stroke(0,1,.4),stroke(0,1,.4)},new boolean[]{true,true},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.rotation(0,0,1,25)},scene.work);sourceContacts(scene,compatible);need(compatible.phase(0)==.4&&compatible.phase(1)==.4,"Source two compatible hard commands exact");CouplerArmConstraint.Stroke[] hard={stroke(0,1,.2),stroke(0,1,.8)};CouplerPoseConstraint.Result failure=CouplerPoseConstraint.solve(scene.model,scene.graph,hard,new boolean[]{true,true},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.IDENTITY},scene.work);need(failure.failure==CouplerPoseConstraint.Failure.UNSAT,"Source incompatible hard commands refuse");failure=CouplerPoseConstraint.solve(scene.model,scene.graph,new CouplerArmConstraint.Stroke[]{stroke(0,1,.9),stroke(0,.2,.1)},new boolean[]{true,false},new RigidTransform[]{RigidTransform.IDENTITY,RigidTransform.IDENTITY},scene.work);need(!failure.accepted(),"Source passive stroke exhaustion refuses");}
 private static void costs()throws Exception{com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);final long id=Thread.currentThread().getId();for(int count:new int[]{2,4,8}){Scene scene=new Scene(count);CouplerArmConstraint.Stroke[] s=new CouplerArmConstraint.Stroke[count];for(int i=0;i<count;i++)s[i]=stroke(0,1,i==0?.25:.75);boolean[] hard=new boolean[count];hard[0]=true;RigidTransform[] r={RigidTransform.IDENTITY,RigidTransform.rotation(0,0,1,35)};final long[] last={-1},between={0};final int[] calls={0};CouplerGraphConstraint.Model measured=(p,o)->{long before=bean.getThreadAllocatedBytes(id);if(last[0]>=0)between[0]+=before-last[0];boolean ok=scene.model.evaluate(p,o);between[0]+=bean.getThreadAllocatedBytes(id)-before;calls[0]++;last[0]=bean.getThreadAllocatedBytes(id);return ok;};for(int i=0;i<3000;i++){last[0]=-1;need(CouplerPoseConstraint.solve(measured,scene.graph,s,hard,r,scene.work).accepted(),"Source cost warmup");}between[0]=0;calls[0]=0;long before=bean.getThreadAllocatedBytes(id),start=System.nanoTime();for(int i=0;i<1000;i++){last[0]=-1;CouplerPoseConstraint.Result result=CouplerPoseConstraint.solve(measured,scene.graph,s,hard,r,scene.work);need(result.accepted(),"Source cost accepted fit");sink=result.phase(count-1);}long nanos=System.nanoTime()-start,bytes=bean.getThreadAllocatedBytes(id)-before;need(between[0]==0&&bytes==(296L+8L*count)*1000,"full Source callback+kernel trial allocation zero; owned result only bytes="+bytes+" between="+between[0]);System.out.println("Source pose cost arms="+count+" solves1000 calls="+calls[0]+" trialBytes="+between[0]+" ownedResultBytes="+bytes+" workOpsLast="+scene.work.workOps()+" retainedBytes="+scene.work.retainedBytes()+" nanos="+nanos);}}
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();Constructor<ArmPayload> constructor=ArmPayload.class.getDeclaredConstructor(VehicleStructure.class,net.minecraft.util.math.BlockPos.class,boolean.class,net.minecraft.util.math.BlockPos.class);constructor.setAccessible(true);Field c=VehicleArmConstraintModelChecks.class.getDeclaredField("constructor");c.setAccessible(true);c.set(null,constructor);make=VehicleArmConstraintModelChecks.class.getDeclaredMethod("arm",GearMotion.Mode.class,EnumFacing.class,int.class,GearMotion.Direction.class,int.class,double.class,double.class);make.setAccessible(true);single();commands();costs();System.out.println("Source coupler pose constraint PASS profiles="+profiles+" checks="+checks+" actual payload callbacks/6mounts/3modes/2sizes/3heights/hardcommands/Ztwist; no runtime or terrain admission");}
 private VehicleCouplerPoseConstraintChecks(){}
}
